/** 
 * Returns true if this actor and all ancestors are visible. 
 */
public boolean ancestorsVisible(){
  Actor actor = this;
  try {
    do {
      if (!actor.isVisible()) return false;
      actor = actor.parent;
    } while (actor != null);
  } catch (NullPointerException e) {
    return false;
  }
  return true;
}
